function Show-AppManager {do{Show-Header;Write-Host "GERENCIAR APPS UWP" -ForegroundColor Yellow;Write-Host "[1] Listar aplicativos UWP";Write-Host "[2] Remover aplicativo por nome";Write-Host "[3] Abrir pagina de apps instalados";Write-Host "[0] Voltar";$o=Read-Host "Opcao";switch($o){"1"{Get-AppxPackage|Sort-Object Name|Select-Object Name,PackageFullName|Format-Table -AutoSize;Pause-WinOptimizer};"2"{$name=Read-Host "Digite o nome exato (ex.: Microsoft.XboxGamingOverlay)";if($name -and Confirm-WinOptimizerAction "Remover $name para todos os usuarios?"){Get-AppxPackage -Name $name -AllUsers|Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue;Write-Status "Comando de remocao enviado para $name." Green;Save-AppliedChange Apps "Remocao UWP" $name};Pause-WinOptimizer};"3"{Start-Process "ms-settings:appsfeatures"};"0"{break}}}while($o -ne "0")}
